/**
 * cross-instance-test-validator must not demand tests for harness scratch files
 * or for files in no git repository (#3892).
 *
 * Two real blocks this pins:
 *   1. A review sub-agent wrote `.../scratchpad/filter_check.py` and the next Stop
 *      demanded `test_filter_check.py` (the report on 10.0.0-alpha.67).
 *   2. On 10.0.0-beta.21 a session whose project dir was a Claude desktop scratch
 *      workspace wrote `agg.py` and the Stop demanded `test_agg.py`. The #3844
 *      project scoping could not help: the file WAS under the project dir.
 */

import { describe, test, expect, beforeEach, afterEach } from 'vitest';
import { appendFileSync, mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import type { HookInput } from '../../types.js';
import { crossInstanceTestValidator, isHarnessScratchPath } from '../../skill/cross-instance-test-validator.js';
import { createTestContext } from '../fixtures/test-context.js';

const SID = 'sid-scratch-3892';
const PY = 'def probe():\n    return 1\n\nclass Aggregator:\n    pass\n';
const TS = 'export function alpha() { return 1; }\n';

let root: string;

function writeFile(full: string, content: string): string {
  mkdirSync(dirname(full), { recursive: true });
  writeFileSync(full, content, 'utf8');
  return full;
}

function recordEdit(project: string, file: string): void {
  const p = join(project, '.claude', 'state', 'edit-history.jsonl');
  mkdirSync(dirname(p), { recursive: true });
  appendFileSync(p, `${JSON.stringify({ t: Date.now(), f: file, tool: 'Write', sid: SID })}\n`);
}

function stop(project: string) {
  const input: HookInput = { tool_name: '', session_id: SID, project_dir: project, tool_input: {}, stop_hook_active: false };
  return crossInstanceTestValidator(input, createTestContext({ projectDir: project, sessionId: SID }));
}

describe('isHarnessScratchPath (#3892)', () => {
  test.each([
    '/Users/me/Library/Application Support/Claude/scratch-workspaces/c5933750/f380bd20/scratch-2026-09-14-d706a0/agg.py',
    '/home/me/.config/Claude/scratch-workspaces/abc/scratch-1/probe.ts',
    '/tmp/claude-1000/-var-www-html/2f1c/scratchpad/filter_check.py',
    '/private/tmp/claude-501/-Users-me-repo/77aa/scratchpad/nested/probe.py',
    `${tmpdir()}/some-session/scratchpad/probe.py`,
  ])('scratch: %s', (p) => {
    expect(isHarnessScratchPath(p)).toBe(true);
  });

  test.each([
    '/Users/me/code/app/src/scratchpad/feature.ts', // a repo dir that happens to be named scratchpad
    '/Users/me/code/app/src/svc.py',
    '/Users/me/code/scratch-workspaces/app/svc.py', // not under a Claude dir
    '/tmp/claude-501/proj/sid/scratchpad', // the file itself, not a dir
  ])('not scratch: %s', (p) => {
    expect(isHarnessScratchPath(p)).toBe(false);
  });
});

describe('cross-instance-test-validator skips scratch and non-git files (#3892)', () => {
  beforeEach(() => {
    root = mkdtempSync(join(tmpdir(), 'citv-3892-'));
  });

  afterEach(() => {
    rmSync(root, { recursive: true, force: true });
  });

  test('Claude desktop scratch workspace as the project dir: no block (the beta.21 repro)', () => {
    const project = join(root, 'Library', 'Application Support', 'Claude', 'scratch-workspaces', 'c593', 'f380', 'scratch-2026-09-14-d706a0');
    const f = writeFile(join(project, 'agg.py'), PY);
    recordEdit(project, f);

    const r = stop(project);

    expect(r.continue).toBe(true);
    expect(r.stopReason).toBeUndefined();
    expect(r.systemMessage).toBeUndefined();
  });

  test('a scratch workspace stays excluded even if someone ran git init in it', () => {
    const project = join(root, 'Claude', 'scratch-workspaces', 'w1', 'scratch-a');
    mkdirSync(join(project, '.git'), { recursive: true });
    const f = writeFile(join(project, 'agg.py'), PY);
    recordEdit(project, f);

    expect(stop(project).continue).toBe(true);
  });

  test('CC session scratchpad under a claude-<uid> dir inside a repo project: no block (the alpha.67 repro)', () => {
    const project = join(root, 'claude-501', '-var-www-html', 'session-1');
    mkdirSync(join(project, '.git'), { recursive: true });
    const f = writeFile(join(project, 'scratchpad', 'filter_check.py'), PY);
    recordEdit(project, f);

    expect(stop(project).continue).toBe(true);
  });

  test('a scratchpad dir under $TMPDIR: no block', () => {
    const project = join(root, 'proj');
    mkdirSync(join(project, '.git'), { recursive: true });
    const f = writeFile(join(project, 'scratchpad', 'probe.ts'), TS);
    recordEdit(project, f);

    expect(stop(project).continue).toBe(true);
  });

  test('a project that is not a git repository: no block', () => {
    const project = join(root, 'plain-dir');
    const f = writeFile(join(project, 'src', 'svc.ts'), TS);
    recordEdit(project, f);

    expect(stop(project).continue).toBe(true);
  });

  test('control: the same untested file in a git repository still blocks', () => {
    const project = join(root, 'repo');
    mkdirSync(join(project, '.git'), { recursive: true });
    const f = writeFile(join(project, 'src', 'svc.ts'), TS);
    recordEdit(project, f);

    const r = stop(project);

    expect(r.continue).toBe(false);
    expect(r.stopReason).toContain(f);
  });

  test('a linked worktree (.git is a file) counts as a git repository', () => {
    const project = join(root, 'wt');
    writeFile(join(project, '.git'), 'gitdir: /somewhere/.git/worktrees/wt\n');
    const f = writeFile(join(project, 'src', 'svc.ts'), TS);
    recordEdit(project, f);

    expect(stop(project).continue).toBe(false);
  });
});
